const RENDER_SIZE: u32 = 32;

#[derive(Clone, Copy, PartialEq, Eq)]
enum ExtraAttachments {
    None = 0,
    Before,
    Between,
    After,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum DummyRenderPass {
    None,
    Dynamic,
    Static,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ColorWriteEnable {
    DontCare,
    Require,
    Disable,
}

#[derive(Clone, Copy)]
struct TestParams {
    color_attachment_count: u32,
    extra_attachment_count: u32,
    extra_attachments: ExtraAttachments,
    extra_fragment_output_count: u32,
    extra_outputs: ExtraAttachments,
    color_format: vk::Format,
    depth_format: vk::Format,
    dummy_render_pass: DummyRenderPass,
    color_write_enable: ColorWriteEnable,
    use_depth_attachment: bool,
    bind_shaders_before_begin_rendering: bool,
    write_gl_frag_depth: bool,
    random_color_formats: bool,
    output_array: bool,
    push_unused_data: bool,
}

fn channel_class_of(format: vk::Format) -> Option<TextureChannelClass> {
    map_vk_format(format).map(|tcu_format| tcu_format.type_.channel_class())
}

fn is_uint_format(format: vk::Format) -> bool {
    channel_class_of(format) == Some(TextureChannelClass::UnsignedInteger)
}

fn is_int_format(format: vk::Format) -> bool {
    channel_class_of(format) == Some(TextureChannelClass::SignedInteger)
}

fn is_float_format(format: vk::Format) -> bool {
    channel_class_of(format) == Some(TextureChannelClass::FloatingPoint)
}

fn image_format_supported(context: &Context<'_>, format: vk::Format, usage: vk::ImageUsageFlags) -> bool {
    unsafe {
        context.get_instance().get_physical_device_image_format_properties(
            context.get_physical_device(),
            format,
            vk::ImageType::_2D,
            vk::ImageTiling::OPTIMAL,
            usage,
            vk::ImageCreateFlags::empty(),
        )
    }
    .is_ok()
}

/// `getClearValue`
fn get_clear_value(tcu_format: TextureFormat) -> vk::ClearValue {
    let channel_class = tcu_format.type_.channel_class();
    if channel_class != TextureChannelClass::SignedInteger && channel_class != TextureChannelClass::UnsignedInteger {
        return vk::ClearValue {
            color: vk::ClearColorValue {
                float32: [0.0, 0.0, 0.0, 1.0],
            },
        };
    }

    let bits = get_texture_format_bit_depth(tcu_format).map(|depth| depth.min(32));
    let sign_bit = i32::from(channel_class == TextureChannelClass::SignedInteger);
    let alpha_max = 1u64.wrapping_shl((bits[3] - sign_bit) as u32).wrapping_sub(1);

    if channel_class == TextureChannelClass::UnsignedInteger {
        vk::ClearValue {
            color: vk::ClearColorValue {
                uint32: [0, 0, 0, alpha_max as u32],
            },
        }
    } else {
        vk::ClearValue {
            color: vk::ClearColorValue {
                int32: [0, 0, 0, alpha_max as u32 as i32],
            },
        }
    }
}

fn clear_color_value_parts(clear_value: vk::ClearValue, class: TextureChannelClass) -> ([f32; 4], [i32; 4]) {
    unsafe {
        match class {
            TextureChannelClass::UnsignedInteger => ([0.0; 4], clear_value.color.uint32.map(|v| v as i32)),
            TextureChannelClass::SignedInteger => ([0.0; 4], clear_value.color.int32),
            _ => (clear_value.color.float32, [0; 4]),
        }
    }
}

struct Rendering<'a> {
    context: &'a Context<'a>,
    params: TestParams,
}

impl Rendering<'_> {
    /// `setColorFormats`
    fn color_formats(&self) -> Vec<vk::Format> {
        let count = (self.params.color_attachment_count + self.params.extra_attachment_count) as usize;
        let mut formats = vec![self.params.color_format; count];
        if self.params.random_color_formats {
            let mut random = Random::new(102030);
            for i in 1..count {
                if i <= self.params.extra_attachment_count as usize
                    && self.params.extra_attachments == ExtraAttachments::Before
                {
                    formats[i] = self.params.color_format;
                } else {
                    loop {
                        // Find a random colour format, and make sure it is supported
                        let format = RANDOM_COLOR_FORMATS[random.get_uint32() as usize % RANDOM_COLOR_FORMATS.len()];
                        if image_format_supported(
                            self.context,
                            format,
                            vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
                        ) {
                            formats[i] = format;
                            break;
                        }
                    }
                }
            }
        }
        formats
    }

    /// `generateExpectedImage`
    fn generate_expected_image(&self, format: vk::Format, attachment_index: u32) -> Result<TextureLevel, TestError> {
        let tcu_format = map_vk_format(format)
            .ok_or_else(|| TestError::NotPorted("colour format without a texture format".to_string()))?;
        let channel_class = tcu_format.type_.channel_class();
        let clear_value = get_clear_value(tcu_format);
        let x_offset = 8;
        let y_offset = 8;

        let mut level = TextureLevel::new(tcu_format, RENDER_SIZE, RENDER_SIZE, 1)?;
        {
            let mut access = level.get_access();
            let (float_color, int_color) = clear_color_value_parts(clear_value, channel_class);
            if channel_class == TextureChannelClass::UnsignedInteger
                || channel_class == TextureChannelClass::SignedInteger
            {
                let _ = clear_int(&mut access, int_color);
            } else {
                clear(&mut access, float_color);
            }
        }

        let p = &self.params;
        let color_count = p.color_attachment_count;
        let is_unused = (p.extra_attachments == ExtraAttachments::Before
            && attachment_index < p.extra_attachment_count)
            || (p.extra_attachments == ExtraAttachments::Between
                && attachment_index > color_count / 2
                && attachment_index <= color_count / 2 + p.extra_attachment_count)
            || (p.extra_attachments == ExtraAttachments::After && attachment_index >= color_count);
        if is_unused {
            return Ok(level);
        }

        let mut set_color = [0.0f32; 4];
        let mut set_color_int = [0i32; 4];
        for i in 0..tcu_format.order.num_used_channels() as usize {
            set_color[i] = 1.0;
            set_color_int[i] = 255;
        }

        let mut access = level.get_access();
        for j in 0..RENDER_SIZE {
            for i in 0..RENDER_SIZE {
                if i >= x_offset && i < RENDER_SIZE - x_offset && j >= y_offset && j < RENDER_SIZE - y_offset {
                    if channel_class == TextureChannelClass::UnsignedInteger
                        || channel_class == TextureChannelClass::SignedInteger
                    {
                        let _ = access.set_pixel_int(set_color_int, i, j, 0);
                    } else {
                        access.set_pixel(set_color, i, j, 0);
                    }
                }
            }
        }
        Ok(level)
    }
}

fn run_rendering(context: &Context<'_>, params: &TestParams) -> TestOutcome {
    // The disabled case needs a device without VK_EXT_color_write_enable, the push data one a device with the descriptor heap feature enabled.
    let second_device = if (params.color_write_enable == ColorWriteEnable::Disable && query_color_write_enable(context))
        || params.push_unused_data
    {
        let excluded: &[&str] = if params.color_write_enable == ColorWriteEnable::Disable {
            &["VK_EXT_color_write_enable"]
        } else {
            &[]
        };
        Some(SecondDevice::new(context, excluded, |_| {})?)
    } else {
        None
    };
    let device = second_device
        .as_ref()
        .map_or_else(|| context.get_device(), |second| second.device());
    let queue = second_device
        .as_ref()
        .map_or_else(|| context.get_universal_queue(), |second| second.queue());
    let allocator = second_device
        .as_ref()
        .map_or_else(|| context.get_default_allocator(), |second| second.allocator());
    let extensions = match &second_device {
        Some(second) => second.extensions().to_vec(),
        None => remove_unsupported_shader_object_extensions(context)?,
    };
    let features = *context.get_device_features();
    let mesh_features = get_mesh_shader_features(context);
    let rendering = Rendering {
        context,
        params: *params,
    };

    let color_format_list = rendering.color_formats();
    let color_attachment_count = (params.color_attachment_count + params.extra_attachment_count) as usize;
    let render_area = rect_2d(RENDER_SIZE, RENDER_SIZE);
    let extent = vk::Extent3D {
        width: RENDER_SIZE,
        height: RENDER_SIZE,
        depth: 1,
    };

    let color_range = make_image_subresource_range(vk::ImageAspectFlags::COLOR, 0, 1, 0, 1);
    let mut depth_range = make_image_subresource_range(vk::ImageAspectFlags::DEPTH, 0, 1, 0, 1);
    if params.use_depth_attachment && map_vk_format(params.depth_format).is_some_and(|f| has_stencil_component(f.order))
    {
        depth_range.aspect_mask |= vk::ImageAspectFlags::STENCIL;
    }

    let image_info = |format: vk::Format, usage: vk::ImageUsageFlags| vk::ImageCreateInfo {
        s_type: vk::StructureType::IMAGE_CREATE_INFO,
        next: std::ptr::null(),
        flags: vk::ImageCreateFlags::empty(),
        image_type: vk::ImageType::_2D,
        format,
        extent: vk::Extent3D {
            width: RENDER_SIZE,
            height: RENDER_SIZE,
            depth: 1,
        },
        mip_levels: 1,
        array_layers: 1,
        samples: vk::SampleCountFlags::_1,
        tiling: vk::ImageTiling::OPTIMAL,
        usage,
        sharing_mode: vk::SharingMode::EXCLUSIVE,
        queue_family_index_count: 0,
        queue_family_indices: std::ptr::null(),
        initial_layout: vk::ImageLayout::UNDEFINED,
    };

    let mut color_images = Vec::new();
    let mut color_views = Vec::new();
    for &format in &color_format_list {
        let image = ImageWithMemory::new(
            device,
            allocator,
            image_info(
                format,
                vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
            ),
            MemoryRequirement::ANY,
        )?;
        color_views.push(make_image_view(
            device,
            image.get(),
            vk::ImageViewType::_2D,
            format,
            color_range,
        )?);
        color_images.push(image);
    }

    let mut depth_image = None;
    let mut depth_view = None;
    if params.use_depth_attachment {
        let image = ImageWithMemory::new(
            device,
            allocator,
            image_info(
                params.depth_format,
                vk::ImageUsageFlags::DEPTH_STENCIL_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
            ),
            MemoryRequirement::ANY,
        )?;
        depth_view = Some(make_image_view(
            device,
            image.get(),
            vk::ImageViewType::_2D,
            params.depth_format,
            depth_range,
        )?);
        depth_image = Some(image);
    }

    let mut color_output_buffers = Vec::new();
    for &format in &color_format_list {
        let pixel_size = map_vk_format(format)
            .and_then(|f| f.pixel_size())
            .ok_or_else(|| TestError::NotPorted("colour format without a pixel size".to_string()))?;
        color_output_buffers.push(BufferWithMemory::new(
            device,
            allocator,
            make_buffer_create_info(
                u64::from(RENDER_SIZE * RENDER_SIZE * pixel_size),
                vk::BufferUsageFlags::TRANSFER_DST,
            ),
            MemoryRequirement::HOST_VISIBLE,
        )?);
    }

    let binaries = context.get_binary_collection();
    let tessellation_supported = features.tessellation_shader != vk::FALSE;
    let geometry_supported = features.geometry_shader != vk::FALSE;
    let vert_shader = create_shader(
        device,
        &make_shader_create_info(
            vk::ShaderStageFlags::VERTEX,
            &binaries.get("vertDepth")?,
            tessellation_supported,
            geometry_supported,
            None,
            None,
        ),
    )?;
    let frag_shader = create_shader(
        device,
        &make_shader_create_info(
            vk::ShaderStageFlags::FRAGMENT,
            &binaries.get("fragMulti")?,
            tessellation_supported,
            geometry_supported,
            None,
            None,
        ),
    )?;

    let cmd_pool = make_command_pool(device, context.get_universal_queue_family_index())?;
    let cmd_buffer = allocate_command_buffer(device, *cmd_pool, vk::CommandBufferLevel::PRIMARY)?;
    let cmd = *cmd_buffer;

    let bind_shaders = || {
        bind_graphics_shaders(
            device,
            cmd,
            vert_shader.get(),
            vk::ShaderEXT::null(),
            vk::ShaderEXT::null(),
            vk::ShaderEXT::null(),
            frag_shader.get(),
            mesh_features.task_shader != vk::FALSE,
            mesh_features.mesh_shader != vk::FALSE,
        );
    };

    begin_command_buffer(device, cmd)?;

    // The dummy image and render pass only have to outlive the command buffer
    let dummy_format = if params.color_format == vk::Format::R8G8B8A8_UNORM {
        vk::Format::R32G32B32A32_SFLOAT
    } else {
        vk::Format::R8G8B8A8_UNORM
    };
    let mut dummy_image = None;
    let mut dummy_view = None;
    let mut dummy_render_pass = None;
    let mut dummy_framebuffer = None;
    if params.dummy_render_pass != DummyRenderPass::None {
        let image = ImageWithMemory::new(
            device,
            allocator,
            image_info(
                dummy_format,
                vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
            ),
            MemoryRequirement::ANY,
        )?;
        let view = make_image_view(device, image.get(), vk::ImageViewType::_2D, dummy_format, color_range)?;

        let barrier = make_image_memory_barrier(
            vk::AccessFlags::empty(),
            vk::AccessFlags::COLOR_ATTACHMENT_WRITE,
            vk::ImageLayout::UNDEFINED,
            vk::ImageLayout::GENERAL,
            image.get(),
            color_range,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::COLOR_ATTACHMENT_OUTPUT,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[] as &[vk::BufferMemoryBarrier],
                &[barrier],
            )
        };

        if params.dummy_render_pass == DummyRenderPass::Static {
            let render_pass = make_render_pass(device, dummy_format)?;
            dummy_framebuffer = Some(make_framebuffer(
                device,
                *render_pass,
                &[*view],
                RENDER_SIZE,
                RENDER_SIZE,
                1,
            )?);
            dummy_render_pass = Some(render_pass);
        }
        dummy_view = Some(view);
        dummy_image = Some(image);
    }
    let _ = &dummy_image;

    let dummy_clear = vk::ClearValue {
        color: vk::ClearColorValue {
            float32: [0.0, 0.0, 0.0, 1.0],
        },
    };
    match params.dummy_render_pass {
        DummyRenderPass::Dynamic => {
            begin_rendering(
                device,
                cmd,
                **dummy_view.as_ref().expect("created above"),
                render_area,
                dummy_clear,
                vk::ImageLayout::GENERAL,
                vk::AttachmentLoadOp::LOAD,
                vk::RenderingFlags::empty(),
                1,
                0,
            );
        }
        DummyRenderPass::Static => {
            let clear_values = [dummy_clear];
            let pass_begin = vk::RenderPassBeginInfo::builder()
                .render_pass(**dummy_render_pass.as_ref().expect("created above"))
                .framebuffer(**dummy_framebuffer.as_ref().expect("created above"))
                .render_area(render_area)
                .clear_values(&clear_values);
            unsafe { device.cmd_begin_render_pass(cmd, &pass_begin, vk::SubpassContents::INLINE) };
        }
        DummyRenderPass::None => {}
    }

    if params.bind_shaders_before_begin_rendering {
        bind_shaders();
    }

    match params.dummy_render_pass {
        DummyRenderPass::Dynamic => end_rendering(device, cmd),
        DummyRenderPass::Static => unsafe { device.cmd_end_render_pass(cmd) },
        DummyRenderPass::None => {}
    }

    for image in &color_images {
        let barrier = make_image_memory_barrier(
            vk::AccessFlags::empty(),
            vk::AccessFlags::COLOR_ATTACHMENT_WRITE,
            vk::ImageLayout::UNDEFINED,
            vk::ImageLayout::GENERAL,
            image.get(),
            color_range,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::COLOR_ATTACHMENT_OUTPUT,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[] as &[vk::BufferMemoryBarrier],
                &[barrier],
            )
        };
    }

    if let Some(image) = &depth_image {
        let barrier = make_image_memory_barrier(
            vk::AccessFlags::empty(),
            vk::AccessFlags::DEPTH_STENCIL_ATTACHMENT_WRITE,
            vk::ImageLayout::UNDEFINED,
            vk::ImageLayout::GENERAL,
            image.get(),
            depth_range,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::EARLY_FRAGMENT_TESTS,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[] as &[vk::BufferMemoryBarrier],
                &[barrier],
            )
        };
    }

    // `beginRendering`
    {
        let float_clear = vk::ClearValue {
            color: vk::ClearColorValue {
                float32: [0.0, 0.0, 0.0, 1.0],
            },
        };
        let depth_clear = vk::ClearValue {
            depth_stencil: vk::ClearDepthStencilValue { depth: 1.0, stencil: 0 },
        };
        let output_count = color_attachment_count + params.extra_fragment_output_count as usize;
        let attachment = |view: vk::ImageView, clear_value: vk::ClearValue| {
            vk::RenderingAttachmentInfo::builder()
                .image_view(view)
                .image_layout(vk::ImageLayout::GENERAL)
                .resolve_mode(vk::ResolveModeFlags::NONE)
                .load_op(vk::AttachmentLoadOp::CLEAR)
                .store_op(vk::AttachmentStoreOp::STORE)
                .clear_value(clear_value)
                .build()
        };
        let null_attachment = || attachment(vk::ImageView::null(), float_clear);

        let mut color_attachments = Vec::with_capacity(output_count);
        if params.extra_outputs == ExtraAttachments::Before
            || (params.extra_outputs == ExtraAttachments::Between && color_attachment_count == 0)
        {
            for _ in 0..params.extra_fragment_output_count {
                color_attachments.push(null_attachment());
            }
        }
        for j in 0..color_attachment_count {
            if params.extra_outputs == ExtraAttachments::Between
                && color_attachments.len() == color_attachment_count / 2 + 1
            {
                for _ in 0..params.extra_fragment_output_count {
                    color_attachments.push(null_attachment());
                }
            }
            color_attachments.push(attachment(
                *color_views[j],
                get_clear_value(
                    map_vk_format(color_format_list[j])
                        .ok_or_else(|| TestError::NotPorted("colour format without a texture format".to_string()))?,
                ),
            ));
        }
        if params.extra_outputs == ExtraAttachments::After
            || (params.extra_outputs == ExtraAttachments::Between && color_attachment_count == 1)
        {
            for _ in 0..params.extra_fragment_output_count {
                color_attachments.push(null_attachment());
            }
        }

        let depth_attachment = depth_view.as_ref().map(|view| attachment(**view, depth_clear));
        let mut rendering_info = vk::RenderingInfo::builder()
            .render_area(render_area)
            .layer_count(1)
            .view_mask(0)
            .color_attachments(&color_attachments);
        if let Some(depth_attachment) = &depth_attachment {
            rendering_info = rendering_info.depth_attachment(depth_attachment);
        }
        unsafe { device.cmd_begin_rendering(cmd, &rendering_info) };
    }

    set_default_shader_object_dynamic_states(
        device,
        cmd,
        &extensions,
        vk::PrimitiveTopology::TRIANGLE_STRIP,
        false,
        false,
        RENDER_SIZE,
        RENDER_SIZE,
    );
    {
        let color_blend_equation = vk::ColorBlendEquationEXT {
            src_color_blend_factor: vk::BlendFactor::ONE,
            dst_color_blend_factor: vk::BlendFactor::ONE,
            color_blend_op: vk::BlendOp::ADD,
            src_alpha_blend_factor: vk::BlendFactor::ONE,
            dst_alpha_blend_factor: vk::BlendFactor::ONE,
            alpha_blend_op: vk::BlendOp::ADD,
        };
        let color_write_mask = vk::ColorComponentFlags::R
            | vk::ColorComponentFlags::G
            | vk::ColorComponentFlags::B
            | vk::ColorComponentFlags::A;
        let count = (color_attachment_count + params.extra_fragment_output_count as usize).max(1);
        unsafe {
            device.cmd_set_color_blend_enable_ext(cmd, 0, &vec![vk::FALSE; count]);
            device.cmd_set_color_blend_equation_ext(cmd, 0, &vec![color_blend_equation; count]);
            device.cmd_set_color_write_mask_ext(cmd, 0, &vec![color_write_mask; count]);
            if params.color_write_enable != ColorWriteEnable::Disable && query_color_write_enable(context) {
                device.cmd_set_color_write_enable_ext(cmd, &vec![vk::TRUE; count]);
            }
            device.cmd_set_depth_write_enable_ext(cmd, true);
            device.cmd_set_depth_test_enable_ext(cmd, true);
            device.cmd_set_depth_compare_op_ext(cmd, vk::CompareOp::LESS);
        }
    }
    bind_null_task_mesh_shaders(device, cmd, &mesh_features);
    if !params.bind_shaders_before_begin_rendering {
        bind_shaders();
    }

    if params.push_unused_data {
        let push_data = [255u8; 256];
        let push_data_info = vk::PushDataInfoEXT {
            offset: 0,
            data: vk::HostAddressRangeConstEXT {
                address: push_data.as_ptr().cast(),
                size: push_data.len(),
            },
            ..Default::default()
        };
        unsafe { device.cmd_push_data_ext(cmd, &push_data_info) };
    }

    unsafe { device.cmd_draw(cmd, 4, 1, 0, 0) };
    end_rendering(device, cmd);

    for image in &color_images {
        let barrier = make_image_memory_barrier(
            vk::AccessFlags::COLOR_ATTACHMENT_WRITE,
            vk::AccessFlags::TRANSFER_READ,
            vk::ImageLayout::GENERAL,
            vk::ImageLayout::GENERAL,
            image.get(),
            color_range,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::COLOR_ATTACHMENT_OUTPUT,
                vk::PipelineStageFlags::TRANSFER,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[] as &[vk::BufferMemoryBarrier],
                &[barrier],
            )
        };
    }

    if let Some(image) = &depth_image {
        let barrier = make_image_memory_barrier(
            vk::AccessFlags::DEPTH_STENCIL_ATTACHMENT_WRITE,
            vk::AccessFlags::TRANSFER_READ,
            vk::ImageLayout::GENERAL,
            vk::ImageLayout::GENERAL,
            image.get(),
            depth_range,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::LATE_FRAGMENT_TESTS,
                vk::PipelineStageFlags::TRANSFER,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[] as &[vk::BufferMemoryBarrier],
                &[barrier],
            )
        };
    }

    let copy_region = make_buffer_image_copy(
        extent,
        make_image_subresource_layers(vk::ImageAspectFlags::COLOR, 0, 0, 1),
    );
    for (image, buffer) in color_images.iter().zip(&color_output_buffers) {
        unsafe {
            device.cmd_copy_image_to_buffer(cmd, image.get(), vk::ImageLayout::GENERAL, buffer.get(), &[copy_region])
        };
    }
    for buffer in &color_output_buffers {
        let barrier = make_buffer_memory_barrier(
            vk::AccessFlags::TRANSFER_WRITE,
            vk::AccessFlags::HOST_READ,
            buffer.get(),
            0,
            vk::WHOLE_SIZE,
        );
        unsafe {
            device.cmd_pipeline_barrier(
                cmd,
                vk::PipelineStageFlags::TRANSFER,
                vk::PipelineStageFlags::HOST,
                vk::DependencyFlags::empty(),
                &[] as &[vk::MemoryBarrier],
                &[barrier],
                &[] as &[vk::ImageMemoryBarrier],
            )
        };
    }

    end_command_buffer(device, cmd)?;
    submit_commands_and_wait(device, queue, cmd)?;

    let width = RENDER_SIZE;
    let height = RENDER_SIZE;
    let x_offset = 8;
    let y_offset = 8;

    let mut unused_begin = 0usize;
    let output_count = (params.color_attachment_count + params.extra_fragment_output_count) as usize;
    match params.extra_attachments {
        ExtraAttachments::Before => unused_begin = 0,
        ExtraAttachments::After => unused_begin = output_count,
        ExtraAttachments::Between => unused_begin = output_count / 2 + 1,
        ExtraAttachments::None => {}
    }
    let unused_end = if params.extra_attachments == ExtraAttachments::None {
        0
    } else {
        unused_begin + params.extra_attachment_count as usize
    };

    for k in 0..color_images.len() {
        if k >= unused_begin && k < unused_end {
            continue;
        }

        let format = color_format_list[k];
        let tcu_format = map_vk_format(format)
            .ok_or_else(|| TestError::NotPorted("colour format without a texture format".to_string()))?;
        let expected = rendering.generate_expected_image(format, k as u32)?;

        invalidate_alloc(device, color_output_buffers[k].get_allocation())?;
        let pixel_size = tcu_format
            .pixel_size()
            .ok_or_else(|| TestError::NotPorted("colour format without a pixel size".to_string()))?
            as usize;
        let data = unsafe {
            std::slice::from_raw_parts(
                color_output_buffers[k].get_allocation().get_host_ptr().cast_const(),
                (width * height) as usize * pixel_size,
            )
        };
        let result = ConstPixelBufferAccess::new(tcu_format, [width, height, 1], data);

        if is_float_format(format) {
            if !float_threshold_compare(&expected.get_const_access(), &result, [0.02; 4]).ok {
                return Ok(TestStatus::fail("Fail"));
            }
        } else if !int_threshold_compare(&expected.get_const_access(), &result, UVec4::new(2, 2, 2, 2)).ok {
            return Ok(TestStatus::fail("Fail"));
        }
    }

    if let Some(image) = &depth_image {
        let depth_buffer = read_depth_attachment(
            context,
            image.get(),
            params.depth_format,
            (width, height),
            vk::ImageLayout::GENERAL,
        )?;
        let depth_access = depth_buffer.get_const_access();

        let depth_epsilon = 0.02f32;
        for j in 0..height {
            for i in 0..width {
                let depth = depth_access.get_pix_depth(i, j, 0);
                let inside = i >= x_offset && i < width - x_offset && j >= y_offset && j < height - y_offset;
                let expected = if inside { 0.5 } else { 1.0 };
                if (depth - expected).abs() > depth_epsilon {
                    log::info!("Depth at ({i}, {j}) is expected to be {expected}, but was ({depth})");
                    return Ok(TestStatus::fail("Fail"));
                }
            }
        }
    }

    Ok(TestStatus::pass("Pass"))
}

fn query_color_write_enable(context: &Context<'_>) -> bool {
    let mut color_write = vk::PhysicalDeviceColorWriteEnableFeaturesEXT::default();
    {
        let mut features2 = vk::PhysicalDeviceFeatures2::builder().push_next(&mut color_write);
        unsafe {
            context
                .get_instance()
                .get_physical_device_features2(context.get_physical_device(), &mut features2)
        };
    }
    color_write.color_write_enable != vk::FALSE
}

struct ShaderObjectRenderingCase {
    name: String,
    params: TestParams,
}

impl TestCase for ShaderObjectRenderingCase {
    fn name(&self) -> &str {
        &self.name
    }

    fn check_support(&self, context: &Context<'_>) -> Result<(), TestError> {
        context.require_device_functionality("VK_EXT_shader_object")?;

        let properties = unsafe {
            context
                .get_instance()
                .get_physical_device_properties(context.get_physical_device())
        };
        let p = &self.params;
        if p.color_attachment_count + p.extra_attachment_count + p.extra_fragment_output_count
            > properties.limits.max_color_attachments
        {
            return Err(TestError::NotSupported(
                "Tests uses more color attachments than VkPhysicalDeviceLimits::maxColorAttachments".to_string(),
            ));
        }

        if !image_format_supported(
            context,
            p.color_format,
            vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
        ) {
            return Err(TestError::NotSupported("Format unsupported for tiling".to_string()));
        }
        if p.use_depth_attachment
            && !image_format_supported(
                context,
                p.depth_format,
                vk::ImageUsageFlags::DEPTH_STENCIL_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
            )
        {
            return Err(TestError::NotSupported("Format unsupported for tiling".to_string()));
        }
        if p.color_write_enable == ColorWriteEnable::Require && !query_color_write_enable(context) {
            return Err(TestError::NotSupported("colorWriteEnable not supported".to_string()));
        }
        if p.push_unused_data {
            context.require_device_functionality("VK_EXT_descriptor_heap")?;
        }
        Ok(())
    }

    fn programs(&self) -> BinaryCollection {
        let p = &self.params;
        let class = if is_uint_format(p.color_format) {
            1
        } else if is_int_format(p.color_format) {
            2
        } else {
            0
        };
        let key = program_key(
            p.color_attachment_count,
            p.extra_attachment_count,
            p.extra_attachments as u32,
            p.extra_fragment_output_count,
            p.extra_outputs as u32,
            class,
            p.random_color_formats,
            p.write_gl_frag_depth,
            p.output_array,
        );
        rendering_programs(&key).unwrap_or(BinaryCollection::new(&[]))
    }

    fn create_instance<'a>(&'a self, context: &'a Context<'a>) -> Box<dyn TestInstance + 'a> {
        Box::new(ShaderObjectRenderingInstance {
            context,
            params: self.params,
        })
    }
}

struct ShaderObjectRenderingInstance<'a> {
    context: &'a Context<'a>,
    params: TestParams,
}

impl TestInstance for ShaderObjectRenderingInstance<'_> {
    fn iterate(&mut self) -> TestOutcome {
        run_rendering(self.context, &self.params)
    }
}

/// `createTestCases`
fn add_format_cases(group: &mut TestCaseGroup, mut params: TestParams) {
    for &(color_format, name) in COLOR_FORMATS {
        if params.extra_attachment_count > params.color_attachment_count {
            continue;
        }
        if !params.bind_shaders_before_begin_rendering && params.dummy_render_pass != DummyRenderPass::None {
            continue;
        }

        params.color_format = color_format;
        params.use_depth_attachment = false;
        params.depth_format = vk::Format::UNDEFINED;

        group.add_child(Box::new(ShaderObjectRenderingCase {
            name: name.to_string(),
            params,
        }) as Box<dyn TestCase>);

        if params.write_gl_frag_depth {
            continue;
        }

        for &(depth_format, depth_name) in DEPTH_FORMATS {
            params.use_depth_attachment = true;
            params.depth_format = depth_format;

            group.add_child(Box::new(ShaderObjectRenderingCase {
                name: format!("{name}_{depth_name}"),
                params,
            }) as Box<dyn TestCase>);
        }
    }
}

/// `createShaderObjectRenderingTests`
pub fn create_shader_object_rendering_tests() -> TestCaseGroup {
    let mut rendering_group = TestCaseGroup::new("rendering");

    let color_attachment_count_tests = [
        (0u32, "color_attachment_count_0"),
        (1, "color_attachment_count_1"),
        (4, "color_attachment_count_4"),
        (8, "color_attachment_count_8"),
    ];
    let extra_attachment_tests = [
        (0u32, ExtraAttachments::None, "none"),
        (1, ExtraAttachments::Before, "extra_attachment_before_1"),
        (1, ExtraAttachments::Between, "extra_attachment_between_1"),
        (1, ExtraAttachments::After, "extra_attachment_after_1"),
        (2, ExtraAttachments::Before, "extra_attachment_before_2"),
        (2, ExtraAttachments::Between, "extra_attachment_between_2"),
        (2, ExtraAttachments::After, "extra_attachment_after_2"),
    ];
    let extra_output_tests = [
        (0u32, ExtraAttachments::None, "none"),
        (1, ExtraAttachments::Before, "extra_output_before_1"),
        (1, ExtraAttachments::Between, "extra_output_between_1"),
        (1, ExtraAttachments::After, "extra_output_after_1"),
        (2, ExtraAttachments::Before, "extra_output_before_2"),
        (2, ExtraAttachments::Between, "extra_output_between_2"),
        (2, ExtraAttachments::After, "extra_output_after_2"),
    ];
    let dummy_render_pass_tests = [
        (DummyRenderPass::None, "none"),
        (DummyRenderPass::Dynamic, "dynamic"),
        (DummyRenderPass::Static, "static"),
    ];

    for (color_attachment_count, color_attachment_name) in color_attachment_count_tests {
        let mut color_attachment_group = TestCaseGroup::new(color_attachment_name);
        for (extra_attachment_count, extra_attachments, extra_attachment_name) in extra_attachment_tests {
            let mut extra_attachment_group = TestCaseGroup::new(extra_attachment_name);
            for (extra_fragment_output_count, extra_outputs, extra_output_name) in extra_output_tests {
                if extra_attachments != ExtraAttachments::None && extra_fragment_output_count != 0 {
                    continue;
                }

                let mut extra_output_group = TestCaseGroup::new(extra_output_name);
                for (dummy_render_pass, dummy_name) in dummy_render_pass_tests {
                    let mut dummy_group = TestCaseGroup::new(dummy_name);
                    for m in 0..2 {
                        let use_random_color_formats = m == 0;
                        if use_random_color_formats && color_attachment_count < 2 {
                            continue;
                        }
                        let mut random_group = TestCaseGroup::new(if use_random_color_formats {
                            "random_color_formats"
                        } else {
                            "same_color_formats"
                        });
                        for k in 0..2 {
                            let bind_shaders_before_begin_rendering = k == 0;
                            let mut bind_group = TestCaseGroup::new(if bind_shaders_before_begin_rendering {
                                "before"
                            } else {
                                "after"
                            });
                            for l in 0..2 {
                                let write_gl_frag_depth = l == 0;
                                let mut frag_depth_group =
                                    TestCaseGroup::new(if write_gl_frag_depth { "gl_frag_write" } else { "none" });

                                add_format_cases(
                                    &mut frag_depth_group,
                                    TestParams {
                                        color_attachment_count,
                                        extra_attachment_count,
                                        extra_attachments,
                                        extra_fragment_output_count,
                                        extra_outputs,
                                        color_format: vk::Format::UNDEFINED,
                                        depth_format: vk::Format::UNDEFINED,
                                        dummy_render_pass,
                                        color_write_enable: ColorWriteEnable::DontCare,
                                        use_depth_attachment: false,
                                        bind_shaders_before_begin_rendering,
                                        write_gl_frag_depth,
                                        random_color_formats: use_random_color_formats,
                                        output_array: false,
                                        push_unused_data: false,
                                    },
                                );
                                bind_group.add_child(frag_depth_group);
                            }
                            random_group.add_child(bind_group);
                        }
                        dummy_group.add_child(random_group);
                    }
                    extra_output_group.add_child(dummy_group);
                }
                extra_attachment_group.add_child(extra_output_group);
            }
            color_attachment_group.add_child(extra_attachment_group);
        }
        rendering_group.add_child(color_attachment_group);
    }

    let color_formats2 = [
        vk::Format::R8_UNORM,
        vk::Format::R8G8B8A8_UNORM,
        vk::Format::R8G8B8A8_SNORM,
        vk::Format::R32_UINT,
        vk::Format::R32_SINT,
        vk::Format::R32_SFLOAT,
        vk::Format::R32G32B32A32_SFLOAT,
    ];

    let mut output_array_group = TestCaseGroup::new("output_array");
    for format in color_formats2 {
        let name = COLOR_FORMATS
            .iter()
            .find(|&&(candidate, _)| candidate == format)
            .map_or("", |&(_, name)| name);
        let mut format_group = TestCaseGroup::new(name);
        let params = TestParams {
            color_attachment_count: 4,
            extra_attachment_count: 2,
            extra_attachments: ExtraAttachments::Between,
            extra_fragment_output_count: 0,
            extra_outputs: ExtraAttachments::None,
            color_format: vk::Format::R8G8B8A8_UNORM,
            depth_format: vk::Format::UNDEFINED,
            dummy_render_pass: DummyRenderPass::None,
            color_write_enable: ColorWriteEnable::Require,
            use_depth_attachment: false,
            bind_shaders_before_begin_rendering: false,
            write_gl_frag_depth: false,
            random_color_formats: false,
            output_array: true,
            push_unused_data: false,
        };
        for (name, color_write_enable) in [
            ("color_write_enable", ColorWriteEnable::Require),
            ("color_write_disable", ColorWriteEnable::Disable),
        ] {
            format_group.add_child(Box::new(ShaderObjectRenderingCase {
                name: name.to_string(),
                params: TestParams {
                    color_write_enable,
                    ..params
                },
            }) as Box<dyn TestCase>);
        }
        output_array_group.add_child(format_group);
    }
    rendering_group.add_child(output_array_group);

    let mut push_data_group = TestCaseGroup::new("push_data");
    push_data_group.add_child(Box::new(ShaderObjectRenderingCase {
        name: "unused".to_string(),
        params: TestParams {
            color_attachment_count: 1,
            extra_attachment_count: 0,
            extra_attachments: ExtraAttachments::None,
            extra_fragment_output_count: 0,
            extra_outputs: ExtraAttachments::None,
            color_format: vk::Format::R8G8B8A8_UNORM,
            depth_format: vk::Format::UNDEFINED,
            dummy_render_pass: DummyRenderPass::None,
            color_write_enable: ColorWriteEnable::DontCare,
            use_depth_attachment: false,
            bind_shaders_before_begin_rendering: false,
            write_gl_frag_depth: false,
            random_color_formats: false,
            output_array: false,
            push_unused_data: true,
        },
    }) as Box<dyn TestCase>);
    rendering_group.add_child(push_data_group);

    rendering_group
}
